import type { Choices, SuggestionOrChoiceType } from './Choice'
import type { StringColumnType } from './String'
import type { Typed } from '../Column'
import type { choiceDropdownType } from './Choice'

/**
 * A Column for a basic image type field.
 *
 * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
 *
 * @param config - an object that can include all base `Column` properties
 */
export function BasicImageColumn<
    const TChoices extends Choices<string>,
    const Type extends SuggestionOrChoiceType<Dropdown, TChoices>,
    const Default extends Type,
    const C extends StringColumnType<TChoices, Dropdown, Type, Default>,
    const Dropdown extends choiceDropdownType = 'none',
>(config: C & StringColumnType<TChoices, Dropdown, Type, Default>) {
    return config as Typed<Type, C>
}
